/**
 * Si Biru — mascot animasi sambutan pasca login/daftar.
 * Sumber aset: file owner "si-biru-loading-v4.html" — sprite & engine asli dihormati penuh.
 * HANYA disuntikkan feed.ts saat URL membawa ?selamat=1 (pengunjung biasa: 0 byte).
 * Urutan suntik: SIBIRU_CSS -> SIBIRU_MARKUP -> SIBIRU_ENGINE_BOOT -> SIBIRU_RUN.
 */
export const SIBIRU_CSS = `
*{box-sizing:border-box}html{color-scheme:light}body{margin:0;min-height:100svh;display:grid;place-items:center;padding:28px 20px;background:radial-gradient(#cbd9e6 1px,transparent 1px) 0 0/25px 25px,#eff6ff;color:#111c2d;font-family:system-ui,-apple-system,sans-serif}.screen{width:min(420px,calc(100vw - 40px));min-width:0;text-align:center}.brand{display:inline-flex;align-items:center;gap:10px;background:#1c56eb;color:#fff;font-size:25px;font-weight:900;letter-spacing:.03em;border:3px solid #111c2d;border-radius:16px;padding:11px 21px;box-shadow:5px 6px #111c2d}.brand svg{width:26px;height:26px}.stage{height:345px;margin:25px 0 23px;border:3px solid #111c2d;border-radius:27px;background:#f5f5f5;box-shadow:5px 6px #111c2d;overflow:hidden}.stage>svg{display:block;width:100%;height:100%}h1{font-size:23px;line-height:1.2;letter-spacing:-.6px;margin:0 0 9px}p{font-size:14px;color:#607084;margin:0;line-height:1.55}.track{position:relative;height:16px;margin:24px auto 20px;max-width:280px;border:3px solid #111c2d;border-radius:12px;background:white;overflow:hidden;box-shadow:3px 4px #111c2d}.bar{height:100%;width:100%;background:#ffdf43;transform:scaleX(.28);transform-origin:left;animation:load 1.8s ease-in-out infinite alternate}@keyframes load{from{transform:translateX(0) scaleX(.28)}to{transform:translateX(65%) scaleX(.35)}}.controls{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-top:25px}button{font:800 11px system-ui;background:white;border:2px solid #111c2d;border-radius:9px;min-height:44px;padding:9px 5px;box-shadow:3px 4px #111c2d;cursor:pointer}button[aria-pressed="true"]{background:#ffdf43}button:active{translate:2px 2px;box-shadow:1px 2px #111c2d}button:focus-visible{outline:3px solid #1756ee;outline-offset:4px}.demo-label{font-size:11px;margin-top:15px}.done .bar{animation:none;transform:scaleX(1);background:#1756ee}.paused .bar,.error .bar{animation-play-state:paused}.exit{opacity:0;transform:translateY(-5px);transition:opacity .28s ease,transform .28s ease}#retry{margin-top:20px}[hidden]{display:none!important}@media(max-width:370px){body{padding:20px 14px}.stage{height:300px}.brand{font-size:23px}h1{font-size:20px}.screen{width:calc(100vw - 28px)}.controls{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}button{padding:9px 5px}}@media(prefers-reduced-motion:reduce){.bar{animation:none;transform:scaleX(.5)}.exit{transition:none}}

/* ==== Integrasi BERBIRRU ==== */
.sibiru-screen { position: fixed; inset: 0; z-index: 2000; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; background: #FBF8F3; padding-top: 7vh; transform: translateX(12px); }
.sibiru-screen .stage { width: min(264px, 72vw) !important; margin: 0 !important; }
.sibiru-screen > * { margin: 0; }
.sibiru-screen .w-kicker { display:inline-block; margin:0 0 14px; font-size:12px; font-weight:900; letter-spacing:.14em; text-transform:uppercase; color:#fff; background:#1c56eb; border:2.5px solid #111c2d; border-radius:999px; padding:6px 14px; box-shadow:3px 3px #111c2d; }
.sibiru-screen .w-hero { margin:0; font-size:29px; font-weight:900; line-height:1.04; letter-spacing:-.01em; color:#111c2d; }
.sibiru-screen .w-hero mark { display:inline-block; background:#FFDF43; color:#111c2d; border:2.5px solid #111c2d; border-radius:9px; box-shadow:3.5px 3.5px #111c2d; padding:1px 10px 3px; transform:rotate(-1.6deg); }
.sibiru-screen .w-tail { margin:15px 0 0; font-size:15.5px; font-weight:800; color:#607084; }
.sibiru-screen .w-tail .dots i { font-style:normal; animation:sibDetik 1.2s infinite; }
.sibiru-screen .w-tail .dots i:nth-child(2) { animation-delay:.2s; }
.sibiru-screen .w-tail .dots i:nth-child(3) { animation-delay:.4s; }
@keyframes sibDetik { 0%,60%,100% { opacity:.25; } 30% { opacity:1; } }
.sibiru-screen .w-kicker, .sibiru-screen .w-hero, .sibiru-screen .w-tail { opacity:0; transform:translateY(20px); animation:sibNaik .6s cubic-bezier(.22,.9,.28,1.18) forwards; }
.sibiru-screen .w-kicker { animation-delay:.05s; }
.sibiru-screen .w-hero { animation-delay:.18s; }
.sibiru-screen .w-tail { animation-delay:.34s; }
@keyframes sibNaik { to { opacity:1; transform:translateY(0); } }
.sibiru-screen.exit { opacity:0; transition:opacity .3s ease; }
@media (prefers-reduced-motion: reduce) {
  .sibiru-screen .welcome *, .sibiru-screen .w-tail .dots i { animation:none !important; opacity:1 !important; transform:none !important; }
}
`;

