export const SIBIRU_ENGINE_BOOT = `
(() => {
'use strict';
const $=id=>document.getElementById(id);
const joints=Object.fromEntries(['character','tail','wing','footL','footR','legL','legR','shadow'].map(id=>[id,$(id)]));
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const screen=$('screen');
let mode='auto',paused=false,time=0,previous=null,raf=0,flapMix=0,destroyed=false;
const TAU=Math.PI*2;
function gait(phase){
 const q=((phase%1)+1)%1;
 // Stance: toe travels backwards on the floor. Swing: toe lifts and returns.
 if(q<.58){const u=q/.58;return {x:16-32*u,y:0,angle:3-6*u};}
 const u=(q-.58)/.42,u2=u*u,u3=u2*u;
 const hermite=(a,b,slope)=>(2*u3-3*u2+1)*a+(u3-2*u2+u)*slope+(-2*u3+3*u2)*b+(u3-u2)*slope;
 // Match stance velocity at both ends, with a smooth lift-off and landing.
 return {x:hermite(-16,16,-32/.58*.42),y:-19*Math.sin(Math.PI*u)**2,angle:hermite(-3,3,-6/.58*.42)-10*Math.sin(TAU*u)*Math.sin(Math.PI*u)};
}
function foot(id,leg,baseX,hipX,t,phase,m,bob,roll){
 const v=gait(phase),x=v.x*(1-m),y=(v.y-bob)*(1-m)+(-10+2*Math.sin(TAU*t/.95))*m;
 const angle=v.angle*(1-m)+(id==='footL'?-9:9)*m;
 const hipY=539,ankleY=580+y;
 // Leg endpoints track the foot and overlap the original body silhouette.
 joints[leg].setAttribute('d',\`M \${hipX} \${hipY} Q \${hipX+x*.4} \${(hipY+ankleY)/2} \${baseX+x} \${ankleY}\`);
 joints[id].setAttribute('transform',\`translate(\${x} \${y}) rotate(\${angle} \${baseX} 585)\`);
}
function pose(t,m){
 const cycle=t/1.25,walk=Math.sin(TAU*cycle),flap=Math.sin(TAU*t/.95);
 const bob=(-2.5+2.5*Math.cos(TAU*cycle*2))*(1-m)+(-17-4*flap)*m;
 const roll=walk*.35*(1-m);
 joints.character.setAttribute('transform',\`translate(0 \${bob}) rotate(\${roll} 330 545)\`);
 // Pivots use the original master coordinates, beneath the body artwork.
 joints.tail.setAttribute('transform',\`rotate(\${-2+walk*2*(1-m)+flap*5*m} 211 480)\`);
 joints.wing.setAttribute('transform',\`rotate(\${12+walk*5*(1-m)+(-49+flap*45)*m} 458 413)\`);
 foot('footL','legL',272,276,t,cycle,m,bob,roll);
 foot('footR','legR',398,397,t,cycle+.5,m,bob,roll);
 joints.shadow.setAttribute('transform',\`translate(330 628) scale(\${1-m*.1} \${1-m*.15}) translate(-330 -628)\`);
}
function tick(now){
 if(destroyed)return;
 const dt=previous===null?0:Math.min(.04,(now-previous)/1000);previous=now;
 if(!paused&&!reduce.matches&&!document.hidden&&!screen.hidden){
  time+=dt;const target=mode==='flap'||(mode==='auto'&&time%10>6)?1:0;
  flapMix+=(target-flapMix)*(1-Math.exp(-dt*5));pose(time,flapMix);
 }
 raf=requestAnimationFrame(tick);
}
function setMode(value){
 if(!['auto','walk','flap'].includes(value))throw new TypeError('Unknown animation mode');
 mode=value;}
const onVisibility=()=>{previous=null;};
const onReduced=()=>{if(reduce.matches){flapMix=0;pose(0,0)}previous=null;};
document.addEventListener('visibilitychange',onVisibility);reduce.addEventListener('change',onReduced);
const pauseSrc=$('pause'); if(pauseSrc) pauseSrc.onclick=e=>{paused=!paused;screen.classList.toggle('paused',paused);e.currentTarget.textContent=paused?'Lanjutkan':'Jeda';e.currentTarget.setAttribute('aria-pressed',String(paused));};
pose(0,0);raf=requestAnimationFrame(tick);
window.berbirruLoading = { setMode };
})();
`;

/** Penutup layar + pembersih URL ?selamat (dipanggil bersamaan dengan markup). */
export const SIBIRU_RUN = `
(function() {
  var scr = document.querySelector('.sibiru-screen');
  if (!scr) return;
  document.body.style.overflow = 'hidden';
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  setTimeout(function() {
    scr.classList.add('exit');
    setTimeout(function() {
      if (scr.parentNode) scr.parentNode.removeChild(scr);
      document.body.style.overflow = '';
    }, reduce ? 0 : 320);
    try {
      var u = new URL(location.href);
      if (u.searchParams.has('selamat')) {
        u.searchParams.delete('selamat');
        var qs = u.searchParams.toString();
        history.replaceState(null, '', u.pathname + (qs ? '?' + qs : '') + u.hash);
      }
    } catch (e) {}
  }, reduce ? 0 : 3200);
})();
`;
